#!/usr/bin/env bash
web_server_helper_setup(){ export RLCH_CIS_2_1_18_STATE_DIR="${BATS_TEST_TMPDIR}/cis-2.1.18/state" RLCH_CIS_2_1_18_STATE_FILE="${BATS_TEST_TMPDIR}/cis-2.1.18/state/packages-removed" RLCH_CIS_2_1_18_PACKAGES="httpd nginx" RLCH_CIS_2_1_18_RPM_COMMAND=rlch_test_web_rpm RLCH_CIS_2_1_18_DNF_COMMAND=rlch_test_web_dnf RLCH_CIS_2_1_18_ID_COMMAND=rlch_test_web_id RLCH_TEST_WEB_HTTPD_INSTALLED=false RLCH_TEST_WEB_NGINX_INSTALLED=false RLCH_TEST_WEB_EFFECTIVE_UID=0 RLCH_TEST_WEB_ID_FAIL=false RLCH_TEST_WEB_DNF_REMOVE_FAIL_PACKAGE="" RLCH_TEST_WEB_DNF_INSTALL_FAIL_PACKAGE="" RLCH_TEST_WEB_KEEP_INSTALLED_AFTER_REMOVE="" RLCH_TEST_WEB_KEEP_REMOVED_AFTER_INSTALL=""; }
rlch_test_web_get_installed(){ case "$1" in httpd) [[ "$RLCH_TEST_WEB_HTTPD_INSTALLED" == true ]];; nginx) [[ "$RLCH_TEST_WEB_NGINX_INSTALLED" == true ]];; *) return 1;; esac; }
rlch_test_web_set_installed(){ case "$1" in httpd) export RLCH_TEST_WEB_HTTPD_INSTALLED="$2";; nginx) export RLCH_TEST_WEB_NGINX_INSTALLED="$2";; *) return 1;; esac; }
rlch_test_web_rpm(){ [[ "${1:-}" == -q ]] || return 1; rlch_test_web_get_installed "${2:-}"; }
rlch_test_web_id(){ [[ "${1:-}" == -u ]] || return 1; [[ "$RLCH_TEST_WEB_ID_FAIL" != true ]] || return 1; printf '%s\n' "$RLCH_TEST_WEB_EFFECTIVE_UID"; }
rlch_test_web_dnf(){ local a="${2:-}" p="${3:-}"; [[ "${1:-}" == -y ]] || return 1; case "$a" in remove) [[ "$RLCH_TEST_WEB_DNF_REMOVE_FAIL_PACKAGE" != "$p" ]] || return 1; [[ "$RLCH_TEST_WEB_KEEP_INSTALLED_AFTER_REMOVE" == "$p" ]] || rlch_test_web_set_installed "$p" false;; install) [[ "$RLCH_TEST_WEB_DNF_INSTALL_FAIL_PACKAGE" != "$p" ]] || return 1; [[ "$RLCH_TEST_WEB_KEEP_REMOVED_AFTER_INSTALL" == "$p" ]] || rlch_test_web_set_installed "$p" true;; *) return 1;; esac; }
